#include<iostream>
using namespace std;
int main(){
    int a,b;
    cout<<"enter the numbers a and b:"<<endl;
    cin>>a>>b;
    int sum=a+b;
    int diff=a-b;
    int product=a*b;
    int division=a/b;
    int modulo=a%b;
    cout<<"sum="<<sum<<endl;
    cout<<"diff="<<diff<<endl;
    cout<<"product="<<product<<endl;
    cout<<"division="<<division<<endl;
    cout<<"reminder="<<modulo<<endl;
    return 0;
    

}